from pathlib import Path
import re
root=Path(__file__).resolve().parent.parent;d=root/'planner'
html=(d/'index.html').read_text().replace('<link rel="stylesheet" href="style.css">','<style>'+(d/'style.css').read_text()+'</style>')
html=html.replace('<th aria-sort="none"><button type="button" class="material-sort" data-sort="reorder"', '<th aria-sort="none"><button type="button" class="material-sort" data-sort="workOrderSupply" aria-label="Sort by Work orders" title="Remaining quantity to be built">Work orders <span class="sort-arrow" aria-hidden="true">↕</span></button></th><th aria-sort="none"><button type="button" class="material-sort" data-sort="reorder"')
modules='\n'.join((d/f).read_text().replace('export ','') for f in ['packing.mjs','core.mjs','catalog.mjs','rollup.mjs','usage.mjs','all-items.mjs','sync.mjs','material-sort.mjs'])
modules=re.sub(r'^import .*;\n','',modules,flags=re.M)
app=re.sub(r'^import .*;\n','',(d/'app.mjs').read_text(),flags=re.M)
app=app.replace("const dataProvider={async load(){return allItemData(catalog,base)}};", "const liveResponse=await fetch('/api/report');const initialReport=liveResponse.ok?await liveResponse.json():{catalog:[],materials:[],lines:[],receipts:[],workOrderReceipts:[],workOrdersConnected:false,issues:[],source:'NetSuite',settingsConnection:'not connected yet',account:'3646375',refreshedAt:null,changeReport:null,settingsMissing:0,sourceCounts:{items:0,activeItems:0,salesOrders:0,uninspectedOrders:0,rawSalesLines:0,rawPOLines:0,rawWorkOrderLines:0,openWorkOrders:0,openPOs:0}};initialReport.lines.forEach(l=>l.preRolledUp=true);catalog.splice(0,catalog.length,...initialReport.catalog);const dataProvider={async load(){return initialReport}};")
app=app.replace('const data=await dataProvider.load();const productLines=', 'let data=await dataProvider.load();let productLines=')
app=app.replace("sample items with settings","live items with settings").replace("r.sample?'Sample data': 'Stock not connected'","r.live?'NetSuite':r.sample?'Sample data':'Stock not connected'")
app=app.replace('if(!r.sample){','if(!r.sample&&!r.live){').replace("rows.filter(r=>!r.sample).length+' awaiting NetSuite'","rows.filter(r=>r.onHand===null).length+' missing stock; '+rows.filter(r=>r.reorder===null).length+' missing reorder settings'")
app=app.replace("r.available===null?'<span class=\"badge neutral\">Awaiting NetSuite</span>'","r.available===null?'<span class=\"badge neutral\">No on-hand value</span>'")
app=app.replace("nf.format(reorder.length)","rows.some(r=>r.suggested!==null)?nf.format(reorder.length):'—'")
app=app.replace('Sample purchase orders · current filters','NetSuite purchase orders · current filters').replace('No sample purchase orders match these filters. Live purchasing data awaits NetSuite.','No open purchase orders match these filters.').replace("receiptLabel[l.timing],'Sample'","receiptLabel[l.timing],'NetSuite'")
app=app.replace("g.purchasing?'Awaiting NetSuite':'Usage only'", "g.purchasing?(num(data.materials.find(m=>String(m.internalId)===String(g.parent.id))?.onHand)+' on hand / '+num(data.materials.find(m=>String(m.internalId)===String(g.parent.id))?.reorder)+' reorder'):'Usage only'")
app=app.replace("$('#update-items').onclick=()=>openRefresh('items');$('#refresh-data').onclick=()=>openRefresh('report');", "$('#update-items').onclick=()=>refreshLive('items');$('#refresh-data').onclick=()=>refreshLive('report');")
app=app.replace("['Hypothetical preview',c.action", "['NetSuite',c.action").replace("'example-item-changes-'+base", "'netsuite-item-changes-'+base")
app=app.replace('<span class="badge warn">Missing reorder point</span>', '<span class="badge neutral" title="No reorder point is set in NetSuite">No suggestion</span>').replace('Start with a preview. Connect your live operations when you’re ready.', 'Live items, inventory, sales orders, purchase orders and reorder settings from NetSuite.')
app=app.replace('<td>${num(r.supply)}</td>', '<td>${num(r.supply)}</td><td>${data.workOrdersConnected?num(r.workOrderSupply):"—"}</td>')
app=app.replace("'All open PO quantity','Projected balance'", "'All open PO quantity','Work orders incoming','WO material demand','Projected balance'").replace('r.available,r.supply,r.projected', 'r.available,r.supply,data.workOrdersConnected?r.workOrderSupply:null,data.workOrdersConnected?r.workOrderDemand:null,r.projected')
app=app.replace('colspan="10"','colspan="11"')
app=app.replace('<div class="detail-section"><h3>Incoming purchase orders</h3>', '<div class="detail-section"><h3>Incoming work orders</h3>${!data.workOrdersConnected?\'<p>Awaiting read access to work orders.</p>\':r.workOrderReceipts.length?\'<div class="table-scroll"><table><thead><tr><th>Work order</th><th>Status</th><th>Expected completion</th><th>Remaining to build</th></tr></thead><tbody>\'+r.workOrderReceipts.map(w=>\'<tr><td>\'+esc(w.order)+\'</td><td>\'+esc(w.status)+\'</td><td>\'+fmt(w.date)+\'</td><td>\'+num(w.qty)+\'</td></tr>\').join(\'\')+\'</tbody></table></div>\':\'<p>No incoming work orders for this material.</p>\'}</div><div class="detail-section"><h3>Incoming purchase orders</h3>')
app=app.replace('${num(r.supply)} incoming =', '${num(r.supply)} on PO + ${num(r.workOrderSupply)} on WO =').replace('All open PO balances count toward reorder coverage.', 'All open PO balances and eligible remaining work-order builds count toward reorder coverage. Work-order material requirements are included in demand.')
app=app.replace('<th>Ship date</th>', '<th>Needed date</th>')
app=app.replace('${esc(l.customer)}', '${esc(l.source==="workOrder"?"Work order components · "+l.status:l.customer)}')
app=app.replace("+' order line missing a ship date'", "+' demand lines missing a needed date'")
app=app.replace('Material is needed on the ship date.', 'Sales material is needed on the ship date; work-order components are needed on the production start date.')
app+= (root/'server/live-ui.js').read_text()
html=html.replace('Sample data<small>Explore before connecting NetSuite</small>','Live NetSuite<small>Read-only · Account 3646375</small>').replace('Demo workspace <span>↗</span>','Live NetSuite <span>↗</span>')
html=html.replace('Preview with sample data','Live NetSuite · Read-only').replace('Your full catalog is loaded. Stock, orders, and purchase orders are examples; unconnected items show —.','Refresh to pull current inventory and orders. Missing reorder settings stay blank.').replace('Sample purchase orders across product lines. Live orders await NetSuite.','Approved open purchase-order balances across all product lines.').replace('ItemSearchResults283.xlsx','NetSuite · Complete item pull').replace('Sample data · No live connection','Live NetSuite · Read-only')
html=html.replace('No stock or reorder settings are in this item export. Order recommendations await NetSuite data.','This calculator uses hypothetical order quantities. View Inventory planner for real order demand and current stock; missing reorder settings stay blank.').replace('Stock and reorder settings will come from NetSuite.','Stock and reorder settings come from NetSuite.').replace('Parent links use names in this export.','Parent links use NetSuite internal IDs.').replace('Connecting NetSuite will replace the demo feed with your inventory, open order lines, and incoming purchase orders.','Live inventory, order data and saved-search reorder settings are loaded.')
html=html.replace('Click a column heading to sort. Select a material to see the orders behind its demand.', 'Near-term demand includes sales orders and work-order components. Work orders shows remaining units to build. Select an item for the details.').replace('<th>Ship date</th>','<th>Needed date</th>')
html=html.replace('<script type="module" src="app.mjs"></script>','<script>(async()=>{'+modules+'\n'+app+'})().catch(e=>{document.querySelector("#page-subtitle").textContent="Unable to load live report: "+e.message});</script>')
(root/'server/live.html').write_text(html)
(root/'server/live-check.js').write_text('(async()=>{'+modules+'\n'+app+'})();')
print('Built local live planner.')
